CREATE SCHEMA owner_read_test;
CREATE FUNCTION owner_read_test.ok(label text, value boolean) RETURNS void LANGUAGE plpgsql AS $fn$
BEGIN IF value IS DISTINCT FROM true THEN RAISE EXCEPTION 'OWNER_READ_FAIL: %', label; END IF;
RAISE NOTICE 'OWNER_READ_PASS: %',label; END $fn$;
CREATE FUNCTION owner_read_test.err(label text, statement text, expected text) RETURNS void LANGUAGE plpgsql AS $fn$
DECLARE observed text;
BEGIN
  BEGIN EXECUTE statement; EXCEPTION WHEN OTHERS THEN GET STACKED DIAGNOSTICS observed=RETURNED_SQLSTATE; END;
  PERFORM owner_read_test.ok(label,observed IS NOT DISTINCT FROM expected);
END $fn$;
GRANT USAGE ON SCHEMA owner_read_test TO anon,authenticated,service_role;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA owner_read_test TO anon,authenticated,service_role;
CREATE TABLE owner_read_test.preserved AS SELECT jsonb_build_object(
 'listings',(SELECT jsonb_agg(to_jsonb(l) ORDER BY id) FROM public.listings l),
 'horses',(SELECT jsonb_agg(to_jsonb(h) ORDER BY id) FROM public.horse_offers h),
 'profiles',(SELECT jsonb_agg(to_jsonb(p) ORDER BY id) FROM public.profiles p)) AS value;

