CREATE FUNCTION owner_read_test.item(p_id text) RETURNS jsonb LANGUAGE sql STABLE AS $fn$
 SELECT x FROM jsonb_array_elements(public.get_my_marketplace_items_v3('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',100)->'items') x WHERE x->>'content_id'=p_id;
$fn$;
GRANT EXECUTE ON FUNCTION owner_read_test.item(text) TO authenticated;

